// Base hiring-intent signals for each company with new jobs today.
return $input.all().map(i => i.json).filter(c => c.company).map(c => {
  const titles = [...new Set((c.sampleTitles || []).map(t => t.toLowerCase()))];
  const seniorities = Object.keys(c.seniority || {}).join(' ').toLowerCase();
  return { json: {
    linkedin: c.companyUrl || c.company,
    company: c.company,
    new_jobs: c.jobsFound || 0,
    distinct_titles: titles.length,
    senior_hire: /director|executive|head/.test(seniorities) || titles.some(t => /\b(head|director|vp|chief|lead)\b/.test(t)),
    ai_jobs: c.aiJobs ?? 0,
    remote_jobs: c.remoteJobs ?? 0,
    titles: (c.sampleTitles || []).slice(0, 5).join(' | '),
    locations: Object.keys(c.topLocations || {}).slice(0, 3).join(' | '),
    latest_job: (c.jobUrls || [])[0] || '',
  } };
});

// Merge today's companies with the tracker: running totals, days seen hiring, 0-100 score and tier.
const cfg = $('Configure').first().json;
const today = new Date().toISOString().slice(0, 10);
const tracked = {};
for (const r of $input.all().map(i => i.json)) if (r.linkedin) tracked[r.linkedin] = r;
return $('Score hiring intent').all().map(i => i.json).map(c => {
  const old = tracked[c.linkedin] || {};
  const totalJobs = Number(old.total_jobs || 0) + c.new_jobs;
  const daysHiring = Number(old.days_hiring || 0) + (old.last_seen === today ? 0 : 1);
  const reasons = [];
  let score = [0, 25, 40, 55][Math.min(c.new_jobs, 3)]; reasons.push(`${c.new_jobs} new job(s) today`);
  if (c.distinct_titles >= 2) { score += 10; reasons.push('several different roles'); }
  if (c.senior_hire) { score += 15; reasons.push('senior hire'); }
  if (c.ai_jobs) { score += 10; reasons.push('AI roles'); }
  if (c.remote_jobs) { score += 5; reasons.push('remote roles'); }
  if (daysHiring >= 2) { score += Math.min(daysHiring * 5, 20); reasons.push(`hiring on ${daysHiring} days, ${totalJobs} jobs so far`); }
  score = Math.min(score, 100);
  return { json: {
    linkedin: c.linkedin,
    company: c.company,
    score,
    tier: score >= cfg.hotScore ? 'hot' : score >= 40 ? 'warm' : 'watch',
    reasons: reasons.join('; '),
    new_jobs_today: c.new_jobs,
    total_jobs: totalJobs,
    days_hiring: daysHiring,
    titles: c.titles,
    locations: c.locations,
    latest_job: c.latest_job,
    first_seen: old.first_seen || today,
    last_seen: today,
  } };
});

const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
// One e-mail: every hot company with its score, the reasons and the AI brief.
const cfg = $('Configure').first().json;
const hot = $input.all().map(i => i.json).sort((a, b) => b.score - a.score);
const cards = hot.map(r => `
  <div style="border-left:4px solid #ff5a1f;padding:8px 12px;margin:0 0 14px">
    <div><b>${esc(r.company)}</b> &middot; score ${r.score} &middot; <a href="${esc(r.linkedin)}">LinkedIn</a>${r.latest_job ? ` &middot; <a href="${esc(r.latest_job)}">latest job</a>` : ''}</div>
    <div style="color:#555">${esc(r.reasons)}<br>Roles: ${esc(r.titles)}</div>
    <p style="margin:8px 0 4px"><b>Why now:</b> ${esc(r.ai_why_now)}<br><b>Angle:</b> ${esc(r.ai_angle)}</p>
    <p style="margin:4px 0"><b>Opening line:</b> <i>${esc(r.ai_opening_line)}</i></p>
    <p style="margin:4px 0;color:#555"><b>Ask:</b> ${esc(r.ai_questions)}</p>
  </div>`).join('');
return [{ json: {
  sendTo: cfg.sendTo,
  subject: `${hot.length} hot hiring account${hot.length > 1 ? 's' : ''} with briefs: ${hot.slice(0, 3).map(r => r.company).join(', ')}`,
  html: `<div style="font-family:Arial,sans-serif;font-size:14px;max-width:680px"><p>Companies hiring hard for ${esc(cfg.jobTitles.split('\n').join(', '))} today, with an account brief for each. The briefs only use the hiring signals; check them before you send anything.</p>${cards}</div>`,
} }];

