// Put each AI brief next to its company (the chain keeps the item order of 'Hot only').
const hot = $('Hot only').all().map(i => i.json);
return $input.all().map((item, k) => {
  const b = item.json.output || {};
  const h = hot[k] || {};
  return { json: {
    linkedin: h.linkedin,
    company: h.company,
    score: h.score,
    reasons: h.reasons,
    titles: h.titles,
    latest_job: h.latest_job,
    ai_why_now: b.why_now || '',
    ai_angle: b.angle || '',
    ai_opening_line: b.opening_line || '',
    ai_questions: (b.discovery_questions || []).join(' | '),
    brief_date: new Date().toISOString().slice(0, 10),
  } };
});
